// n8n Code Node - Latest ToolCallId Extractor
// Ultra-efficient extraction of the latest toolCallId from webhook payload

try {
  // Direct access to toolCalls array from webhook
  const toolCalls = $('Webhook').first().json.body.message.toolCalls;

  // Fast validation and extraction
  if (!Array.isArray(toolCalls) || toolCalls.length === 0) {
    return [{
      json: {
        latestToolCallId: null,
        error: 'No toolCalls found or empty array',
        totalToolCalls: 0,
        extractedAt: new Date().toISOString()
      }
    }];
  }

  // Get the latest (last) toolCall - most efficient approach
  const latestIndex = toolCalls.length - 1;
  const latestToolCall = toolCalls[latestIndex];

  // Extract the ID with validation
  const latestToolCallId = latestToolCall?.id || null;

  if (!latestToolCallId) {
    return [{
      json: {
        latestToolCallId: null,
        error: `ToolCall at index ${latestIndex} missing id property`,
        totalToolCalls: toolCalls.length,
        latestIndex: latestIndex,
        extractedAt: new Date().toISOString()
      }
    }];
  }

  // Success - return the latest toolCallId
  return [{
    json: {
      latestToolCallId: latestToolCallId,
      latestIndex: latestIndex,
      totalToolCalls: toolCalls.length,
      extractedAt: new Date().toISOString()
    }
  }];

} catch (error) {
  // Error handling
  return [{
    json: {
      latestToolCallId: null,
      error: `Extraction failed: ${error.message}`,
      totalToolCalls: 0,
      extractedAt: new Date().toISOString()
    }
  }];
}

try {
  const input = $input.first().json;

  // Get messages from messagesOpenAIFormatted array
  const messages = input?.body?.message?.artifact?.messagesOpenAIFormatted;
  const combinedContent = [];

  if (Array.isArray(messages)) {
    for (let i = 1; i < messages.length; i++) {
      const content = messages[i]?.content;
      if (content) {
        combinedContent.push(content);
      }
    }
  }

  // Get latest tool call
  const toolCalls = input?.body?.message?.toolCalls;
  let latestToolName = null;
  let latestToolArgs = "";

  if (Array.isArray(toolCalls) && toolCalls.length > 0) {
    const lastIndex = toolCalls.length - 1;
    const lastTool = toolCalls[lastIndex]?.function;

    latestToolName = lastTool?.name || null;

    // Handle arguments (may be stringified JSON or object)
    let args = lastTool?.arguments;
    if (typeof args === "string") {
      try {
        args = JSON.parse(args);
      } catch (e) {
        args = {};
      }
    }

    if (args && typeof args === "object") {
      // Convert args object into a single string
      latestToolArgs = Object.entries(args)
        .map(([key, value]) => `${key}: ${value}`)
        .join(", ");
    }
  }

  // Return result
  return [{
    json: {
      combinedContent: combinedContent.join('\n\n'),
      totalMessagesFound: combinedContent.length,
      latestToolName,
      latestToolArgs, // single string variable with all key-value pairs
      extractedAt: new Date().toISOString()
    }
  }];

} catch (error) {
  return [{
    json: {
      combinedContent: '',
      totalMessagesFound: 0,
      latestToolName: null,
      latestToolArgs: '',
      error: error.message,
      extractedAt: new Date().toISOString()
    }
  }];
}
